'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { UserGroupIcon, PlusIcon, MagnifyingGlassIcon } from '@heroicons/react/24/outline';
import { formatDate } from '@/lib/utils';

// Mock data for development
const mockUsers = [
  {
    id: '1',
    name: 'John Doe',
    email: 'john.doe@pos.com',
    role: 'admin',
    branch_id: '1',
    is_active: true,
    created_at: '2024-01-15T10:30:00Z',
    updated_at: '2024-03-10T14:20:00Z',
    last_login: '2024-03-12T09:15:00Z',
    branch: { name: 'Main Branch' },
  },
  {
    id: '2',
    name: 'Jane Smith',
    email: 'jane.smith@pos.com',
    role: 'manager',
    branch_id: '2',
    is_active: true,
    created_at: '2024-02-01T09:15:00Z',
    updated_at: '2024-03-05T11:30:00Z',
    last_login: '2024-03-12T08:30:00Z',
    branch: { name: 'North Branch' },
  },
  {
    id: '3',
    name: 'Mike Johnson',
    email: 'mike.johnson@pos.com',
    role: 'staff',
    branch_id: '1',
    is_active: false,
    created_at: '2024-01-20T13:45:00Z',
    updated_at: '2024-02-28T16:45:00Z',
    last_login: '2024-03-10T16:45:00Z',
    branch: { name: 'Main Branch' },
  },
];

export default function UsersPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredUsers, setFilteredUsers] = useState(mockUsers);

  useEffect(() => {
    const filtered = mockUsers.filter(user =>
      user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.role.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredUsers(filtered);
  }, [searchTerm]);

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'admin': return 'status-error';
      case 'manager': return 'status-warning';
      case 'staff': return 'status-success';
      default: return 'status-secondary';
    }
  };

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Page Header */}
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-primary">Users</h1>
              <p className="mt-1 text-sm text-text-secondary">
                Manage user accounts and permissions
              </p>
            </div>
            <button className="btn-primary">
              <PlusIcon className="h-5 w-5 mr-2" />
              Add User
            </button>
          </div>

          {/* Search */}
          <div className="card p-4">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MagnifyingGlassIcon className="h-5 w-5 text-text-secondary" />
              </div>
              <input
                type="text"
                placeholder="Search users..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="input-field w-full pl-10"
              />
            </div>
          </div>

          {/* Users Table */}
          <div className="card overflow-hidden">
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-divider">
                <thead className="bg-surface">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      User
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Email
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Role
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Branch
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Status
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      Last Login
                    </th>
                    <th className="relative px-6 py-3 text-left text-xs font-medium text-text-secondary uppercase tracking-wider">
                      <span>Actions</span>
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-card divide-y divide-divider">
                  {filteredUsers.map((user) => (
                    <tr key={user.id} className="hover:bg-surface">
                      <td className="px-6 py-4">
                        <div className="flex items-center space-x-3">
                          <div className="h-8 w-8 bg-primary/10 rounded-full flex items-center justify-center">
                            <span className="text-sm font-medium text-primary">
                              {user.name.split(' ').map(word => word[0]).join('').toUpperCase()}
                            </span>
                          </div>
                          <div>
                            <div className="text-sm font-medium text-primary">{user.name}</div>
                            <div className="text-xs text-text-secondary">{user.email}</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-sm text-text-secondary">
                        {user.email}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${getRoleColor(user.role)}`}>
                          {user.role}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-text-secondary">
                        {user.branch?.name}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                          user.is_active ? 'status-success' : 'status-error'
                        }`}>
                          {user.is_active ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-text-secondary">
                        {formatDate(user.last_login)}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-left text-sm">
                        <button className="text-primary hover:bg-primary/10 p-1 rounded transition-colors">
                          <UserGroupIcon className="h-4 w-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {filteredUsers.length === 0 && (
            <div className="text-center py-12">
              <UserGroupIcon className="h-12 w-12 text-text-secondary mx-auto mb-4" />
              <h3 className="text-lg font-medium text-primary mb-2">No users found</h3>
              <p className="text-text-secondary">Try adjusting your search criteria</p>
            </div>
          )}
        </div>
      </Layout>
    </AuthGuard>
  );
}
